    var hrGroup = '00a1366bc33bcb90150658e1b40131ec';
    var itGroup = '34c13eabc33bcb90150658e1b4013178';

    var map = {
        'hr': hrGroup,
        'payroll': hrGroup,
        'it': itGroup,
        'access': itGroup
    };

    var category = ('' + current.x_2240531_employ_0_category.getDisplayValue()).toLowerCase();

    gs.addInfoMessage('BR fired. category=[' + category + ']');

    if (map[category]) {
        current.assignment_group = map[category];
    }

})(current, previous);
